query:
query ($owner: String!, $repo: String!) {
  repository(owner: $owner, name: $repo) {
    qualified: refs(refPrefix: "refs/heads/", query: "refs/heads/suggestion-pr/", first: 100) { totalCount }
    heads: refs(refPrefix: "refs/heads/", query: "heads/suggestion-pr/", first: 100) { totalCount }
    caret: refs(refPrefix: "refs/heads/", query: "^suggestion-pr/", first: 100) { totalCount }
    glob: refs(refPrefix: "refs/heads/", query: "suggestion-pr/*", first: 100) { totalCount }
    slashMid: refs(refPrefix: "refs/heads/", query: "suggestions/36/", first: 100) { totalCount nodes { name } }
    page1: refs(refPrefix: "refs/heads/", query: "suggestion-pr/", first: 10, orderBy: {field: ALPHABETICAL, direction: ASC}) { totalCount pageInfo { hasNextPage endCursor } nodes { name } }
  }
}
